      //   เดิมเว็บหัก 100/80 สำหรับกรอบ 10 ซม. ตามไฟล์ตัดประกอบ Fuji เก่า → คิ้วสั้นเกิน
      BEADV: '0.16',   // หักคิ้วตั้ง  80+80
      BEADH: '0.12',   // หักคิ้วขวาง 60+60
      // ── ตัวเลือกอุปกรณ์ (ชีต v1 ช่อง I2:J7) ──
      HWB: "((spec&&spec.odhwcolor)||'ขาว')==='ดำ' ? 1 : 0",
      HD1: "((spec&&spec.odhandle)||'คิงโบ ล็อค+กุญแจ')",
      HD2: "((spec&&spec.odhandle2)||'ไม่ใส่')",
