    //   ของจริงคุมด้วย "จำนวนบาน" (P) อยู่แล้ว — บาน 2 = บานพับ 8 · มือจับ 2 · วงกบ 2 ชุด ตรงกับใบตัดทุกตัว
    //   ใบตัด velora_swing = 1 บาน 1 ชุดวงกบ แล้วคูณจำนวนบาน (multiplier) → ไฟล์ไม่มีแบบ "คู่ใช้วงกบร่วม"
    //   forms: [] = ซ่อน dropdown (UI เช็ค prod.forms?.length > 0) เหลือช่องจำนวนบานช่องเดียว ไม่ให้เลือกซ้ำซ้อน
