      LONGV: "(function(){var v=(form==='ตั้ง' ? H*100 : W*100),V=[50,60,75,100,120,150,200,300,600];for(var i=0;i<V.length;i++){if(V[i]>=v)return V[i];}return v;})()",   // ยาว/ใบ (ตามแนวเกล็ด)
