    //   เดิมเป็นก้อนเดียวใน consum ไม่มีรหัส (เหมาซื้อเส้น) → หน้าเทียบขึ้น "มีแต่ใบตัด" ทุกครั้ง
    //   ปัดขึ้นเส้นเต็มด้วย packBars (เจ้าของเคาะ 27 ส.ค.69) — จัดชิ้นลงเส้นจริง เหมือนประตูรั้ว
    // เวฟ 5 (16 ก.ย.69): รื้อ 4 บรรทัดจันทันให้ตรง หลังคา_ตัด #1/#2/#3/#7 (เดิมยุบเป็น "รัดรอบกว้าง ×2" + "ซอย ×E2")
    //   #1 ฝั่งบ้าน = ยัดในช่องจันทัน (ยาวเท่าแป × จำนวนช่อง) · #7 ฝั่งปลาย = ยื่นปลาย → เต็มกว้าง−0.4 ×1 · อื่น ๆ → ยัดในช่อง
