      PURROWS: 'Math.ceil(E2/50)+1',                                                          // แถวแปต่อสโลป
      DBLP: "spec.batten==='แปคู่'?2:1",   // ค่าตั้งต้นรุ่นนี้คือแปคู่ (ต่างจากกันสาดที่ตั้งต้นแปเดี่ยว)
      RIDGELEN: 'Dc-10.2',                                                                    // สัน/อกไก่ ยาวรวม
      nRafterBars: 'Math.ceil(E2/600)',
      nDeepBars: 'Math.ceil(Dc/600)',
